def zipf_coverage(m: int, k_classes: int, s: float) -> float:
    if not 0 <= m <= k_classes:
        raise ValueError("need 0 ≤ m ≤ K")

    def harmonic(upto: int) -> float:
        return sum(k ** (-s) for k in range(1, upto + 1))

    return harmonic(m) / harmonic(k_classes)

